SELECT a.id,a.project_id AS "projectId",a.device_id AS "deviceId",d.name AS machine,(SELECT jsonb_build_object('id',id,'operation',operation,'status',CASE WHEN status IN('requested','received') AND expires_at<=now() THEN 'expired' ELSE status END) FROM controls c WHERE c.workspace_id=a.workspace_id AND c.attempt_id=a.id ORDER BY created_at DESC,c.id LIMIT 1) AS control,p.repository,a.issue_number AS "issueNumber",a.base_sha AS "baseSha",a.candidate_sha AS "candidateSha",a.phase,a.state,a.reason_code AS "reasonCode",a.version,a.evidence,progress.action AS "nextAction",(SELECT jsonb_build_object('digest',digest,'baseSha',base_sha,'candidateSha',candidate_sha,'sharedAt',created_at) FROM shared_diffs f WHERE f.workspace_id=a.workspace_id AND f.attempt_id=a.id AND f.candidate_sha=a.candidate_sha AND f.version=a.version) AS "sharedDiff",a.updated_at AS "updatedAt",CASE WHEN d.revoked OR d.last_contact < now()-interval '2 minutes' THEN 'disconnected' ELSE 'connected' END AS connection FROM attempt_reports a JOIN devices d ON d.id=a.device_id JOIN projects p ON p.id=a.project_id LEFT JOIN attempt_progression progress ON (progress.workspace_id,progress.id)=(a.workspace_id,a.id) WHERE a.workspace_id=$1 ORDER BY a.updated_at DESC,a.id LIMIT 500
